const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});
const leadId = String(payload.leadId || payload.id || '').trim();
const recipientName = String(payload.recipientName || payload.contactName || '').trim();
const companyName = String(payload.companyName || payload.company || '').trim();
const contactEmail = String(payload.contactEmail || payload.email || '').trim().toLowerCase();
const opportunityType = String(payload.opportunityType || 'L4_performance').trim();
const rawEvidence = Array.isArray(payload.evidence) ? payload.evidence : [];

if (rawEvidence.length === 0) {
  return [{
    json: {
      eventId: item.eventId,
      status: 'processed',
      draftResult: {
        status: 'insufficient_evidence',
        reason: 'Master Directive non-fabrication rule: cannot generate outreach without verified technical evidence.',
        draft: null
      }
    }
  }];
}

return [{
  json: {
    eventId: item.eventId,
    leadId,
    recipientName,
    companyName,
    contactEmail,
    opportunityType,
    evidence: rawEvidence,
    complianceCleared: Boolean(payload.complianceCleared ?? true),
    noRecentDuplicate: Boolean(payload.noRecentDuplicate ?? true)
  }
}];

const item = $input.first().json;
if (item.draftResult && item.draftResult.status === 'insufficient_evidence') {
  return [{ json: item }];
}

const company = item.companyName || 'your team';
const recipient = item.recipientName ? item.recipientName.split(' ')[0] : 'there';
const evidenceList = item.evidence;
const primaryFact = evidenceList[0] || 'Core Web Vitals latency observed during technical audit';

let subject = '';
let observation = '';
let impact = '';
let cta = '';

switch (item.opportunityType) {
  case 'L4_performance':
    subject = 'Technical observation on ' + company + ' web performance';
    observation = 'While reviewing frontend architecture in ' + company + "'s sector, our automated probe noted that " + primaryFact + '.';
    impact = 'On mobile connections, this delays interactive paint and creates initial viewport hesitation for prospective users.';
    cta = 'Would you like me to send over the raw technical breakdown so your engineering team can review it?';
    break;
  case 'L5_mobile_ux':
    subject = 'Note on ' + company + ' mobile browsing layout';
    observation = 'During our engineering inspection of ' + company + ', we observed: ' + primaryFact + '.';
    impact = 'Mobile viewports encounter layout shifts during initial load that affect user navigation.';
    cta = 'Happy to share the mobile audit diagnostic if that would be helpful for your team.';
    break;
  case 'L6_conversion':
  case 'L7_seo_foundation':
    subject = 'Engineering note regarding ' + company + ' technical metadata';
    observation = 'In our recent web architecture audit of ' + company + ', we identified: ' + primaryFact + '.';
    impact = 'This limits how search indexers catalog your service endpoints and impacts client discoverability.';
    cta = 'Let me know if you would like the full diagnostic report to inspect with your engineers.';
    break;
  default:
    subject = 'Engineering architecture note for ' + company;
    observation = 'We recently completed a technical analysis where we noted: ' + primaryFact + '.';
    impact = 'Addressing this foundational architecture enables reliable scaling and modern web performance.';
    cta = 'Would you be open to reviewing the technical analysis report?';
}

const body = [
  'Hi ' + recipient + ',',
  '',
  observation,
  '',
  impact,
  '',
  cta,
  '',
  'Best regards,',
  'Vikash Saravanan',
  'Lead System Engineer | Logic Intelligence Technologies'
].join('\n');

const generatedOutput = {
  subject,
  observation,
  impact,
  cta,
  body
};

return [{
  json: {
    ...item,
    generatedOutput
  }
}];

const item = $input.first().json;
if (item.draftResult && item.draftResult.status === 'insufficient_evidence') {
  return [{ json: item }];
}

const out = item.generatedOutput || {};
const text = [out.subject, out.observation, out.impact, out.cta, out.body].join(' ');

const unsupportedPatterns = [
  /\b(you(?:'re| are)?|your business)\s+losing\b/i,
  /\blos(?:e|ing)\s+(?:customers|clients|sales|revenue|business|leads)\b/i,
  /\bcosting you\b/i,
  /\bcosting\s+(?:you\s+)?(?:thousands|millions|\$|₹|lakhs|crores)\b/i,
  /\bbounce rate\b/i,
  /\bconversion(?:s)?\s+(?:are|is)\s+(?:dropping|down|low)\b/i,
  /\byour conversion rate\b/i,
  /\bcustomers?\s+(?:are\s+)?(?:leaving|hitting dead ends)\b/i,
  /\b\d{1,3}\s*%\s+of\s+(?:your\s+)?(?:mobile\s+)?(?:traffic|visitors|customers)\b/i
];

const sensationalPatterns = [
  /\burgent\b/i,
  /\bact now\b/i,
  /\bguaranteed? (?:growth|results|roi)\b/i,
  /\bdouble your (?:sales|revenue|traffic)\b/i,
  /\bsecret strategy\b/i,
  /\blimited time\b/i,
  /!!+/
];

const placeholderPattern = /\{\{[^}]+\}\}|\[[a-z_ ]+\]/i;
const genericOpener = /^\s*(?:hi[^.]*,?\s*)?we are\b/i;
const meetingDemand = /\b(?:book|schedule|grab)\s+(?:a\s+)?(?:call|meeting|slot|time|30\s*mins?)\b/i;

const gates = [];

const claimSafetyPass = !unsupportedPatterns.some(p => p.test(text));
gates.push({ key: 'claim_safety', pass: claimSafetyPass, blocker: true, detail: claimSafetyPass ? 'No unsupported revenue/conversion claims' : 'Violates claim safety' });

const specificityPass = !placeholderPattern.test(text);
gates.push({ key: 'specificity', pass: specificityPass, blocker: true, detail: specificityPass ? 'All template placeholders resolved' : 'Unfilled placeholders detected' });

const tonePass = !sensationalPatterns.some(p => p.test(text));
gates.push({ key: 'tone', pass: tonePass, blocker: true, detail: tonePass ? 'Professional, engineering-first tone' : 'Sensational wording detected' });

const frictionPass = !meetingDemand.test(text);
gates.push({ key: 'friction', pass: frictionPass, blocker: true, detail: frictionPass ? 'Low-friction CTA offering value' : 'Demanding meeting before value established' });

const personalizationPass = !genericOpener.test(out.body) && Boolean(item.companyName);
gates.push({ key: 'personalization', pass: personalizationPass, blocker: true, detail: personalizationPass ? 'Personalized to recipient context' : 'Generic agency opener' });

const compliancePass = Boolean(item.complianceCleared);
gates.push({ key: 'compliance', pass: compliancePass, blocker: true, detail: compliancePass ? 'Jurisdiction cleared & suppression checked' : 'Failed compliance check' });

const duplicationPass = Boolean(item.noRecentDuplicate);
gates.push({ key: 'duplication', pass: duplicationPass, blocker: true, detail: duplicationPass ? 'No recent duplicate outreach' : 'Duplicate outreach detected' });

const factualityPass = Array.isArray(item.evidence) && item.evidence.length > 0;
gates.push({ key: 'factuality', pass: factualityPass, blocker: true, detail: factualityPass ? 'Grounding evidence confirmed' : 'Missing grounding facts' });

const blockersPass = gates.filter(g => g.blocker).every(g => g.pass);
const score = Math.round((gates.filter(g => g.pass).length / gates.length) * 100);

return [{
  json: {
    ...item,
    gates,
    blockersPass,
    qaScore: score
  }
}];

const item = $input.first().json;
if (item.draftResult && item.draftResult.status === 'insufficient_evidence') {
  return [{
    json: {
      eventId: item.eventId,
      status: 'processed',
      draftResult: item.draftResult
    }
  }];
}

const crypto = require('crypto');
const draftId = crypto.randomUUID();

const draftRecord = {
  id: draftId,
  leadId: item.leadId,
  companyName: item.companyName,
  recipientEmail: item.contactEmail,
  recipientName: item.recipientName,
  subject: item.generatedOutput.subject,
  body: item.generatedOutput.body,
  channel: 'email',
  status: 'pending_approval',
  approvedBy: null,
  approvedAt: null,
  blockersPass: item.blockersPass,
  qaScore: item.qaScore,
  gates: item.gates,
  createdAt: new Date().toISOString()
};

return [{
  json: {
    eventId: item.eventId,
    status: 'processed',
    draftResult: {
      status: item.blockersPass ? 'draft_created' : 'review_blocked',
      draft: draftRecord
    }
  }
}];

const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const eventId = item.json.eventId;
const ts = String(Math.floor(Date.now() / 1000));
const payload = {
  eventId,
  status: item.json.status || 'processed',
  detail: { draftResult: item.json.draftResult }
};
const rawBody = JSON.stringify(payload);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
return [{ json: { eventId, status: payload.status, rawBody, timestamp: ts, signature: 'v1=' + mac } }];
